<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">←</text><text class="nav-title">正则可视化</text><text class="nav-icon empty"> </text></view></view><view class="content"><view class="rx-input-row"><input class="rx-input" v-model="pattern" placeholder="正则表达式" /><input class="rx-input" v-model="flags" placeholder="标（gi）" style="width:120rpx"/></view><textarea class="rx-text" v-model="testStr" placeholder="测试文本..." maxlength="1000" auto-height /><view class="rx-result" v-if="matches.length"><text class="rx-match" v-for="(m, idx) in matches" :key="idx">{{ m }}</text></view><view class="rx-empty" v-else><text>无匹配</text></view></view></view></template><script setup>import { ref, computed, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const pattern = ref("\d+"); const flags = ref("g"); const testStr = ref("Hello 123 World 456")
const matches = computed(function() { try { return testStr.value.match(new RegExp(pattern.value, flags.value)) || [] } catch(e) { return [] } })
function goBack() { uni.navigateBack() }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#e17055,#d63031);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:48rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.rx-input-row{display:flex;gap:16rpx;margin-bottom:24rpx}.rx-input{flex:1;height:80rpx;background:#fff;border-radius:16rpx;padding:0 20rpx;font-size:28rpx;font-family:monospace}.rx-text{width:100%;min-height:200rpx;background:#fff;border-radius:20rpx;padding:24rpx;font-size:28rpx;box-sizing:border-box;margin-bottom:24rpx}.rx-result{background:#fff;border-radius:20rpx;padding:24rpx;display:flex;flex-wrap:wrap;gap:12rpx}.rx-match{background:#e84393;color:#fff;padding:8rpx 16rpx;border-radius:8rpx;font-size:26rpx;font-family:monospace}.rx-empty{text-align:center;padding:40rpx;font-size:26rpx;color:#999}</style>